CREATE COLUMN TABLE "TEST_AP"."OLTB" ("AbsId" INTEGER CS_INT NOT NULL , "LocCode" INTEGER CS_INT, "STAType" INTEGER CS_INT, "STACode" NVARCHAR(8), "BalaType" NVARCHAR(1), "Balance" DECIMAL(21,6) CS_FIXED, PRIMARY KEY ("AbsId")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."OLTB" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$LocCode$STAType$STACode$','LocCode','STAType','STACode'));
CREATE INDEX "OLTB_index" ON "TEST_AP"."OLTB" ( "LocCode" ASC, "STAType" ASC, "STACode" ASC )